        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$source=IssuerPolicy::id($source);$key=CompanyInvoiceCopiesInput::key($key);$review=CompanyInvoiceCopiesInput::review($review);$formHash=CompanyInvoiceCopiesInput::hash($review);
        $prepared=$this->store->tx(function()use($issuer,$actor,$source,$key,$review,$formHash):array{$current=$this->store->sourceOwned($issuer,$actor,$source,false);$row=$this->store->requestOwned($key,$issuer,$actor,$source);if($row){$e=CompanyInvoiceCopiesOrigin::evidence($row,$issuer,$actor,$source,$key);if($row['form_hash']!==$formHash)throw new DomainException('company_invoice_copy_conflict');return ['row'=>$row,'input'=>$e['input'],'replay'=>true];}
            $current=$this->store->sourceOwned($issuer,$actor,$source);if($current['revision']!==$review['source_revision'])throw new DomainException('company_invoice_copy_stale');$input=['client_id'=>$current['client_id'],'date'=>$review['date'],'due_date'=>$review['due_date'],'currency'=>$current['currency_id'],'items'=>$current['items'],'note'=>$review['note']]+$current['options'];$json=CompanyInvoiceCopiesInput::json($input);$row=['request_key'=>$key,'issuer_id'=>$issuer,'actor_id'=>$actor,'source_invoice_id'=>$source,'source_client_id'=>$current['client_id'],'source_status'=>$current['status'],'source_number'=>$current['number'],'source_revision'=>$review['source_revision'],'form_hash'=>$formHash,'input_hash'=>hash('sha256',$json),'canonical_hash'=>CompanyInvoiceCopiesInput::hash(CompanyInvoiceCopiesInput::canonical($input)),'canonical_request_key'=>CompanyInvoiceCopiesOrigin::canonicalKey($issuer,$actor,$source,$key),'input_json'=>$json,'result_invoice_id'=>null,'result_json'=>null,'result_hash'=>null,'created_at'=>gmdate('Y-m-d H:i:s'),'finalized_at'=>null];return ['row'=>$row,'input'=>$input,'replay'=>false];});
        $origin=new CompanyInvoiceCopiesOrigin($this->store,$issuer,$actor,$source,$key,$prepared);$id=(new CompanyInvoices($this->db,$this->p))->create($issuer,$actor,$prepared['input'],$prepared['row']['canonical_request_key'],$origin,$this->store->tables());return ['invoice_id'=>$id,'request_key'=>$key];
